import{_ as i,C as r,c as a,o as l,j as n,G as d,a2 as s,a as o}from"./chunks/framework.CIiVzG-O.js";const b=JSON.parse('{"title":"Herunterladen & installieren","description":"Laden Sie qDiff für den Mac, prüfen Sie die Systemvoraussetzungen und starten Sie Ihren ersten Vergleich.","frontmatter":{"title":"Herunterladen & installieren","description":"Laden Sie qDiff für den Mac, prüfen Sie die Systemvoraussetzungen und starten Sie Ihren ersten Vergleich."},"headers":[],"relativePath":"de/guide/download.md","filePath":"de/guide/download.md","lastUpdated":1794296122000}'),u={name:"de/guide/download.md"};function h(m,e,c,f,g,p){const t=r("DownloadButtons");return l(),a("div",null,[e[0]||(e[0]=n("h1",{id:"herunterladen-installieren",tabindex:"-1"},[o("Herunterladen & installieren "),n("a",{class:"header-anchor",href:"#herunterladen-installieren","aria-label":'Permalink to "Herunterladen & installieren"'},"​")],-1)),e[1]||(e[1]=n("p",null,"qDiff ist eine kleine, native Mac-App. Installieren Sie sie, und der erste Vergleich ist nur zwei Ziehbewegungen entfernt.",-1)),d(t),e[2]||(e[2]=s('<h2 id="in-einem-moment-installiert" tabindex="-1">In einem Moment installiert <a class="header-anchor" href="#in-einem-moment-installiert" aria-label="Permalink to &quot;In einem Moment installiert&quot;">​</a></h2><ol><li>Öffnen Sie die Mac-App-Store-Seite und klicken Sie auf <strong>Holen</strong>, dann auf <strong>Installieren</strong>.</li><li>Starten Sie qDiff aus dem Ordner „Programme“ oder über das Launchpad.</li><li>Ziehen Sie zwei Dateien — oder zwei Ordner — ins Fenster. Das war die ganze Einrichtung.</li></ol><div class="tip custom-block"><p class="custom-block-title">Zugriff auf einen Ordner erlauben</p><p>Wenn Sie zum ersten Mal einen Ordner vergleichen, fragt macOS möglicherweise, ob qDiff hineinsehen darf. Wählen Sie <strong>Erlauben</strong>. Sie behalten die Kontrolle: Es werden nur Ordner gelesen, die Sie auswählen, und Sie können dies später in den Einstellungen ändern.</p></div><h2 id="system-requirements" tabindex="-1">Systemvoraussetzungen <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;Systemvoraussetzungen {#system-requirements}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>System</td><td>macOS 12 oder neuer</td></tr><tr><td>Mac</td><td>Apple-Chip und Intel</td></tr><tr><td>Konto</td><td>Nicht erforderlich</td></tr><tr><td>Internet</td><td>Für den Vergleich nicht erforderlich</td></tr><tr><td>Sprachen</td><td>Englisch, vereinfachtes Chinesisch, traditionelles Chinesisch, Japanisch, Deutsch, Spanisch und Französisch</td></tr><tr><td>Darstellung</td><td>Hell und dunkel</td></tr></tbody></table><h2 id="kostenlos-mit-optionalem-einmaligem-kauf" tabindex="-1">Kostenlos, mit optionalem einmaligem Kauf <a class="header-anchor" href="#kostenlos-mit-optionalem-einmaligem-kauf" aria-label="Permalink to &quot;Kostenlos, mit optionalem einmaligem Kauf&quot;">​</a></h2><p>Jeder Vergleich, jede Ansicht und jeder Export funktioniert ohne Bezahlung. Die kostenlose Version zeigt lediglich einen „Nicht lizenziert“-Hinweis in der Tableiste. Ein einmaliger Kauf entfernt diesen Hinweis und schließt künftige Premium-Extras ein — kein Abo, keine Werbung, kein Konto. Käufe sind an Ihre Apple ID gebunden und können jederzeit in den Einstellungen wiederhergestellt werden.</p><p>Lesen Sie die <a href="./introduction.html">Einführung</a> oder gehen Sie direkt zum <a href="./files.html">Vergleich von Dateien</a>.</p>',8))])}const k=i(u,[["render",h]]);export{b as __pageData,k as default};
